CREATE OR REPLACE FUNCTION private.cancel_simulated_booking(p_booking uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare booking public.bookings%rowtype; trip_id uuid;
begin
 if auth.uid() is null then raise exception 'Sign in first' using errcode='42501'; end if;
 if not exists(select 1 from private.payment_configuration where id and simulation_enabled) then raise exception 'Simulation disabled' using errcode='42501'; end if;
 select ride_id into trip_id from public.bookings where id=p_booking and rider_id=auth.uid() and payment_provider='simulated';
 if trip_id is null then raise exception 'Simulated booking not found'; end if;
 perform 1 from public.rides where id=trip_id for update;
 select * into booking from public.bookings where id=p_booking for update;
 if booking.status='cancelled' then return booking.id; end if;
 if booking.status<>'confirmed' then raise exception 'Booking cannot be cancelled'; end if;
 update public.bookings set status='cancelled',payment_status='refunded' where id=p_booking;
 update public.rides set seats_available=seats_available+booking.seats_booked where id=trip_id;
 return p_booking;
end $function$
CREATE OR REPLACE FUNCTION private.transition_ride(trip uuid, next_status text)
 RETURNS rides
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare current_trip public.rides;
begin
 select * into current_trip from public.rides where id=trip for update;
 if auth.uid() is null or current_trip.id is null or (current_trip.driver_id<>auth.uid() and not private.is_approved_admin()) then raise exception 'Ride access denied' using errcode='42501'; end if;
 if not ((current_trip.status='active' and next_status in ('in_progress','cancelled')) or (current_trip.status='in_progress' and next_status in ('completed','cancelled'))) then raise exception 'Invalid ride transition'; end if;
 if next_status='cancelled' and exists(select 1 from public.bookings where ride_id=trip and payment_status='paid' and status<>'cancelled') then raise exception 'Refund paid bookings before cancelling this ride'; end if;
 update public.rides set status=next_status where id=trip returning * into current_trip;
 if next_status='completed' then update public.bookings set status='completed' where ride_id=trip and status='confirmed'; end if;
 if next_status='cancelled' then update public.bookings set status='cancelled' where ride_id=trip and status in ('pending','confirmed'); end if;
 return current_trip;
end $function$
